import React, { useState, useEffect } from "react";
import axios from "axios";
import "./AdminDashboard.css";  // create this file for styling

export default function AdminDashboard() {
  const [ngos, setNgos] = useState([]);
  const [topPerformers, setTopPerformers] = useState({});
  const [reports, setReports] = useState({});
  const [loading, setLoading] = useState(true);

  const token = localStorage.getItem("token");

  useEffect(() => {
    fetchDashboardData();
  }, []);

  async function fetchDashboardData() {
    try {
      const headers = { Authorization: `Bearer ${token}` };

      const [ngosRes, topRes, reportRes] = await Promise.all([
        axios.get("/api/ngos", { headers }),
        axios.get("/api/top-performers", { headers }),
        axios.get("/api/reports", { headers })
      ]);

      setNgos(ngosRes.data.ngos);
      setTopPerformers(topRes.data);
      setReports(reportRes.data);
      setLoading(false);

    } catch (e) {
      console.error("Dashboard load error:", e);
      setLoading(false);
    }
  }

  async function deleteNGO(id) {
    try {
      await axios.delete(`/api/remove-ngo/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setNgos(ngos.filter(n => n.id !== id));
    } catch (e) {
      console.error("Delete error:", e);
    }
  }

  if (loading) return <h2>Loading...</h2>;

  return (
    <div className="admin-container">
      
      {/* BOX 1 – TOTAL NGOs */}
      <div className="card">
        <h2>Total NGOs</h2>
        <p className="big-number">{ngos.length}</p>
        <div className="scroll-box">
          {ngos.map((n) => (
            <div className="list-item" key={n.id}>
              <span>{n.name}</span>
              <button className="delete-btn" onClick={() => deleteNGO(n.id)}>
                Delete
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* BOX 2 – TOTAL DONATIONS */}
      <div className="card">
        <h2>Total Donations</h2>
        <p className="big-number">{reports.donations?.length || 0}</p>
        <div className="scroll-box">
          {reports.donations?.map((d) => (
            <div className="list-item" key={d.id}>
              <span>₹{d.amount} - {d.name}</span>
            </div>
          ))}
        </div>
      </div>

      {/* BOX 3 – TOTAL VOLUNTEERING */}
      <div className="card">
        <h2>Volunteers Count</h2>
        <p className="big-number">{reports.volunteers?.length || 0}</p>
        <div className="scroll-box">
          {reports.volunteers?.map((v) => (
            <div className="list-item" key={v.id}>
              <span>{v.name} → {v.event_title}</span>
            </div>
          ))}
        </div>
      </div>

      {/* BOX 4 – TOP VOLUNTEER */}
      <div className="card highlight">
        <h2>Top Volunteer</h2>
        {topPerformers.topVolunteer ? (
          <div>
            <h3>{topPerformers.topVolunteer.name}</h3>
            <p>Events: {topPerformers.topVolunteer.total_events}</p>
          </div>
        ) : <p>No data yet.</p>}
      </div>

      {/* BOX 5 – TOP NGO */}
      <div className="card highlight">
        <h2>Top NGO</h2>
        {topPerformers.topNGO ? (
          <div>
            <h3>{topPerformers.topNGO.name}</h3>
            <p>Total Donations: ₹{topPerformers.topNGO.total_donations}</p>
          </div>
        ) : <p>No data yet.</p>}
      </div>

      {/* BOX 6 – TOP EVENT */}
      <div className="card highlight">
        <h2>Top Event</h2>
        {topPerformers.topEvent ? (
          <div>
            <h3>{topPerformers.topEvent.title}</h3>
            <p>Volunteers: {topPerformers.topEvent.volunteers_count}</p>
            <p>Donations: ₹{topPerformers.topEvent.donations_sum}</p>
          </div>
        ) : <p>No data yet.</p>}
      </div>

    </div>
  );
}
